{"command":"psql "postgresql://u_47c0e64be211:${RUSTY_SECRET_1}@simcloud:5433/crm__prod__crm?sslmode=disable" -v ON_ERROR_STOP=1 -c "
BEGIN;
CREATE TEMP TABLE duplicates AS
   SELECT c.id, c.tenant_id, c.email_norm, s.survivor_id
   FROM contacts c
   JOIN (
     SELECT id AS survivor_id, tenant_id, email_norm
     FROM (
       SELECT id, tenant_id, email_norm,
              ROW_NUMBER() OVER (PARTITION BY tenant_id, email_norm ORDER BY created_at, id) AS rn
       FROM contacts
       WHERE status = 'active'
     ) ranked
     WHERE rn = 1
   ) s ON c.tenant_id = s.tenant_id AND c.email_norm = s.email_norm
   WHERE c.status = 'active'
     AND c.id <> s.survivor_id;

UPDATE contacts
SET status = 'merged', merged_into = duplicates.survivor_id
FROM duplicates
WHERE contacts.id = duplicates.id;

UPDATE activities
SET contact_id = duplicates.survivor_id
FROM duplicates
WHERE activities.contact_id = duplicates.id;

UPDATE deals
SET contact_id = duplicates.survivor_id
FROM duplicates
WHERE deals.contact_id = duplicates.id;

DROP TABLE duplicates;
COMMIT;
""}

